import { inject, Injectable, signal } from '@angular/core';
import { StockService } from '../stock/stock.service';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { NotificationsService } from '../_services/notifications.service';
import { ApiService } from '../_services/api.service';
import { HistoryService } from '../history/history.service';
import { AuxiliaryService } from '../accounting/auxiliary.service';
import { AccountingService } from '../accounting/accounting.service';
import { BehaviorSubject } from 'rxjs';
import {
    InvoiceItems,
    InvoiceTotals,
    PendingInvoices,
} from '../core/interfaces/customer.interface';
import * as moment from 'moment';

@Injectable({
    providedIn: 'root',
})
export class OrderService {
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService,
        private historyService: HistoryService,
        private stockService: StockService,
        private auxiliaryService: AuxiliaryService,
        private accountingService: AccountingService
    ) {}

    private host = this.api.host;

    orderSubmitLoading = signal(false);

    public invoice_items = new BehaviorSubject<InvoiceItems[]>([]);
    public invoiceTotal = new BehaviorSubject<InvoiceTotals>(null);
    public barcodeResponse = new BehaviorSubject<any>(0);
    public factor = new BehaviorSubject<number>(1);
    stateOptions = new BehaviorSubject([
        { label: '$$', value: 'dollar' },
        { label: 'L.L', value: 'lira' },
    ]);
    stateValue = new BehaviorSubject<'dollar' | 'lira'>('dollar');
    public customer_id = new BehaviorSubject(null);
    public active_invoice = new BehaviorSubject(-1);
    public pending_invoices$ = new BehaviorSubject<PendingInvoices[]>([]);
    public reset_form_validations$ = new BehaviorSubject(false);

    public include_vat = false;
    public vat_rate = 0.11;
    public discount_value = null;
    public discount_percent = null;
    public discount_percent_on_total = null;
    public invoice_date = moment().format('YYYY-MM-DD');
    public form_error = false;
    submitted = false;

    public priceOption = 'original';

    // sell dialog
    sellDialogVisible = new BehaviorSubject<boolean>(false);

    public invoice_number = null;
    public invoice_number_error = false;
    current_invoice_number = null;

    deliveryChargeValue = this.stockService.deliveryChargeValue;

    //init invocie values
    init_values() {
        this.submitted = false;
        this.include_vat = false;
        this.discount_value = null;
        this.discount_percent = null;
        this.discount_percent_on_total = null;
        this.customer_id.next(null);
        this.invoice_date = moment().format('YYYY-MM-DD');
    }
    // submit barcode
    submitBarcode(barcode) {
        this.http.get(`${this.host}/stock/item/${barcode}`).subscribe({
            next: (item) => {
                if (item) {
                    this.barcodeResponse.next(item);
                } else {
                    this.notificationService.showError(
                        'Item not found!',
                        'home'
                    );
                }
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    calculate_additional_totals(invoice_totals: InvoiceTotals) {
        if (invoice_totals.total_dollar_price === 0) {
            invoice_totals.discount_amount_dollar = 0;
            invoice_totals.discount_amount_lira = 0;
            invoice_totals.vat_dollar = 0;
            invoice_totals.vat_lira = 0;
            invoice_totals.delivery_charge = 0;

            this.invoiceTotal.next(invoice_totals);

            return;
        }
        const exchangeRate = this.stockService.exchangeRate.value as any;
        invoice_totals.total_dollar = invoice_totals.total_dollar_price;

        if (exchangeRate.rate_value) {
            invoice_totals.total_lira =
                invoice_totals.total_dollar * exchangeRate.rate_value;

            invoice_totals.total_lira_price =
                invoice_totals.total_dollar_price * exchangeRate.rate_value;
        }

        if (this.discount_value || this.discount_percent) {
            //calculate discount ammounts
            invoice_totals.discount_amount_dollar = this.discount_value
                ? this.discount_value
                : Math.round(
                      invoice_totals.total_dollar_price * this.discount_percent
                  ) / 100;
            invoice_totals.discount_amount_lira = this.discount_value
                ? this.discount_value * exchangeRate.rate_value
                : (invoice_totals.total_lira_price * this.discount_percent) /
                  100;

            if (
                invoice_totals.discount_amount_dollar >
                invoice_totals.total_dollar_price
            ) {
                this.discount_value = null;
                this.discount_percent = null;
                invoice_totals.discount_amount_dollar =
                    invoice_totals.discount_amount_lira = 0;
            }
        } else {
            invoice_totals.discount_amount_dollar = 0;
            invoice_totals.discount_amount_lira = 0;
        }
        //subtract discount from total
        invoice_totals.total_lira =
            invoice_totals.total_lira - invoice_totals.discount_amount_lira;
        invoice_totals.total_dollar =
            invoice_totals.total_dollar - invoice_totals.discount_amount_dollar;

        if (this.discount_percent_on_total) {
            const dicount_amount =
                Math.round(
                    invoice_totals.total_dollar * this.discount_percent_on_total
                ) / 100;

            if (dicount_amount > invoice_totals.total_dollar) {
                this.discount_percent_on_total = null;
                invoice_totals.secondary_discount_amount_dollar = 0;
            } else {
                invoice_totals.secondary_discount_amount_dollar =
                    dicount_amount;
            }
        } else {
            invoice_totals.secondary_discount_amount_dollar = 0;
        }

        //subtract secondary discount from total
        invoice_totals.total_dollar =
            invoice_totals.total_dollar -
            invoice_totals.secondary_discount_amount_dollar;
        invoice_totals.total_lira =
            invoice_totals.total_lira -
            invoice_totals.secondary_discount_amount_dollar *
                exchangeRate.rate_value;

        invoice_totals.total_dollar_discount_2 = invoice_totals.total_dollar;

        //calculate vat totals
        if (this.include_vat) {
            invoice_totals.vat_lira = invoice_totals.total_lira * this.vat_rate;
            invoice_totals.vat_dollar =
                invoice_totals.total_dollar * this.vat_rate;
        } else {
            invoice_totals.vat_lira = 0;
            invoice_totals.vat_dollar = 0;
        }
        invoice_totals.total_lira =
            invoice_totals.total_lira + invoice_totals.vat_lira;
        invoice_totals.total_dollar =
            invoice_totals.total_dollar + invoice_totals.vat_dollar;

        //save value
        this.invoiceTotal.next(invoice_totals);
    }
    // calculate total cost and price
    calculateTotal(operation = 'add') {
        let order_items = this.invoice_items.value;
        if (!order_items) return;

        let invoice_totals: InvoiceTotals = {
            total_dollar_price: 0,
            total_lira_price: 0,
            total_dollar_cost: 0,
            total_lira_cost: 0,
            total_dollar: 0,
            total_lira: 0,
            total_dollar_discount_2: 0,
            discount_amount_dollar: 0,
            secondary_discount_amount_dollar: 0,
            discount_amount_lira: 0,
            vat_lira: 0,
            vat_dollar: 0,
            total_qty: 0,
        };
        order_items.forEach((item) => {
            invoice_totals.total_dollar_cost =
                invoice_totals.total_dollar_cost +
                item.quantity * item.unit_cost;
            invoice_totals.total_dollar_price =
                invoice_totals.total_dollar_price +
                item.quantity * item.unit_price;
            invoice_totals.total_qty += item.quantity;
        });
        this.calculate_additional_totals(invoice_totals);
    }

    checkout(invoice, invoiceMap, customer) {
        this.orderSubmitLoading.set(true);
        this.http.post(`${this.host}/orders`, [invoice, invoiceMap]).subscribe({
            next: (res: any) => {
                this.orderSubmitLoading.set(false);
                this.notificationService.showSuccess(res.message, 'home');
                this.stockService.getItems();
                this.reset_form_validations$.next(true);
                this.cleanInvoice();
                this.historyService.fetchSalesHistory(null);
            },
            error: (error: HttpErrorResponse) => {
                this.orderSubmitLoading.set(false);
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    cleanInvoice() {
        this.init_values();
        this.invoice_items.next([]);
        this.calculateTotal();
        this.reset_form_validations$.next(true);
    }
}
