import { Injectable, signal } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { BehaviorSubject } from 'rxjs';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ApiService } from '../_services/api.service';

@Injectable({
    providedIn: 'root',
})
export class HistoryService {
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService,
    ) {
        // this.fetchSalesHistory({
        //     invoice_number: null,
        //     customer_id: null,
        //     invoice_date: null,
        // });
        this.fetchPurchasesHistory({
            invoice_number: null,
            supplier_id: null,
            invoice_date: null,
        });
        this.fetchReturnHistory({
            invoice_number: null,
            customer_id: null,
            invoice_date: null,
        });
    }

    private host = this.api.host;
    salesHistory = new BehaviorSubject([]);
    returnHistory = new BehaviorSubject([]);
    loading = new BehaviorSubject<boolean>(false);
    detailsDialogVisible = new BehaviorSubject<boolean>(false);
    editDialogVisible = new BehaviorSubject<boolean>(false);
    editOrdersDialogVisible = signal(false);
    editReturnDialogVisible = signal(false);
    purchasesHistory = new BehaviorSubject([]);

    editPurchaseDialogVisible = signal(false);

    public printLoading: boolean = false;

    fetchSalesHistory(form) {
        this.loading.next(true);
        this.http.post(`${this.host}/history/sales/search`, form).subscribe({
            next: (res: any) => {
                this.salesHistory.next(res);
                this.loading.next(false);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'history');
            },
        });
    }

    ordersHistory = signal([]);
    fetchOrdersHistory(
        form = {
            customer_id: null,
            invoice_date: null,
        },
    ) {
        this.loading.next(true);
        this.http.post(`${this.host}/history/orders/search`, form).subscribe({
            next: (res: any) => {
                this.ordersHistory.set(res);
                this.loading.next(false);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'history');
            },
        });
    }

    fetchReturnHistory(
        form = { invoice_number: null, customer_id: null, invoice_date: null },
    ) {
        this.loading.next(true);
        this.http.post(`${this.host}/history/return/search`, form).subscribe({
            next: (res: any) => {
                this.returnHistory.next(res);
                this.loading.next(false);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'history');
            },
        });
    }

    fetchPurchasesHistory(
        form = { invoice_number: null, supplier_id: null, invoice_date: null },
    ) {
        this.loading.next(true);
        this.http
            .post(`${this.host}/history/purchases/search`, form)
            .subscribe({
                next: (res: any) => {
                    this.purchasesHistory.next(res);
                    this.loading.next(false);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'history',
                    );
                },
            });
    }

    // complete order
    completeOrder(data) {
        this.http.post(`${this.host}/orders/complete`, data).subscribe({
            next: (res) => {
                this.notificationService.showSuccess(
                    'Order created successfully!',
                    'home',
                );
                this.fetchOrdersHistory();
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.showError(error.error, 'home');
            },
        });
    }
}
